import sys

def solve():
	inp = sys.stdin.readline
	n = int(inp())
	a = list(map(int, inp().split()))
	b = list(map(int, inp().split()))
	st = [(int(1000000000.0 + 7), n)]
	next = [None] * n
	for i in range(n - 1, -1, -1):
		v = b[i]
		while st[-1][0] <= v:
			st.pop()
		next[i] = st[-1][1]
		st.append((v, i))
	m = int(inp())
	have = dict()
	for v in map(int, inp().split()):
		have[v] = have.get(v, 0) + 1
	need = dict()
	last = dict()
	for i in range(n):
		if a[i] < b[i]:
			print('NO')
			return
		if a[i] == b[i]:
			continue
		v = b[i]
		val = last.get(v, None)
		if val is None:
			need[v] = 1
		elif next[val] < i:
			need[v] += 1
		last[v] = i
	for (k, v) in need.items():
		if have.get(k, 0) < v:
			print('NO')
			return
	print('YES')

def main():
	for i in range(int(sys.stdin.readline())):
		solve()
main()
